<main class="content container-fluid catalog-page"><header class="catalog-page-head"><div><span class="eyebrow">CONFIGURACIÓN GENERAL</span><h2>Catálogos del sistema</h2><p>Administra los valores utilizados en usuarios, tests y tabuladores.</p></div><span class="catalog-total"><?=count($roles)+count($subjects)+count($groups)+count($subgroups)?> registros</span></header><div class="catalog-compact-grid"><?php foreach([['roles','R','Roles de usuario','Permisos y niveles de acceso',$roles],['subjects','A','Asignaturas','Áreas asociadas a docentes',$subjects],['tabulator_groups','G','Grupos de tabuladores','Organización principal',$groups],['tabulator_subgroups','S','Subgrupos de tabuladores','Clasificación secundaria',$subgroups]] as [$type,$icon,$label,$description,$items]):?><section class="catalog-card"><header><span class="catalog-card-icon"><?=$icon?></span><div><h3><?=e($label)?></h3><p><?=e($description)?></p></div><span class="catalog-card-count"><?=count($items)?></span><a class="catalog-add" href="<?=url('/admin/catalogos/formulario?type='.$type)?>" title="Agregar registro" aria-label="Agregar <?=e($label)?>">+</a></header><?php if(!$items):?><div class="catalog-empty">Sin registros</div><?php else:?><div class="catalog-rows"><?php foreach($items as $i):?><div class="catalog-row"><div><span>#<?=$i['id']?></span><strong><?=e($i['name'])?></strong></div><div class="catalog-actions"><a href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'].'&mode=view')?>" title="Ver">Ver</a><a href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'])?>" title="Editar">Editar</a><form method="post" action="<?=url('/admin/catalogos/eliminar')?>" onsubmit="return confirm('¿Eliminar este registro?')"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button title="Eliminar">Eliminar</button></form></div></div><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></div></main>
